const PHONE_NUMBER_ID = '1353516234507857';
const raw = $input.first().json || {};
const list = Array.isArray(raw.mandates) ? raw.mandates : [];
const items = [];
const seenTg = {};
const seenWa = {};
for (const m of list) {
  if (!m || m.active === false) continue;
  if (m.pings === false || m.pings === 'false') continue;
  const wa = String(m.whatsapp_group_id || '').trim();
  const tg = String(m.telegram_chat_id || '').trim();
  const ask = 'Daily scholarship deadline check-in. If a scholarship season is approaching, encourage the room to finish the Scholarship path and take the lab so they can qualify. Name the end date and days left from scholarship_live. Never post a discount code — course reps give it out. Never name a student. Ask which lesson they are on. If there is no approaching deadline, stay silent.';
  if (wa && !seenWa[wa]) {
    seenWa[wa] = true;
    items.push({
      json: {
        department: 'community',
        task_description: ask,
        context_data: {
          channel: 'whatsapp',
          chat_kind: 'group',
          department: 'community',
          action: 'scholarship_nudge',
          group_id: wa,
          mandate: m,
          phone_number_id: PHONE_NUMBER_ID
        }
      }
    });
  }
  if (tg && !seenTg[tg]) {
    seenTg[tg] = true;
    items.push({
      json: {
        department: 'community',
        task_description: ask,
        context_data: {
          channel: 'telegram',
          chat_kind: 'group',
          department: 'community',
          action: 'scholarship_nudge',
          telegram_chat_id: tg,
          chat_id: tg,
          mandate: m
        }
      }
    });
  }
}
return items;

const worker = $input.first().json || {};
const preps = $('Prepare nudge').all();
const prep = ((preps[$itemIndex] || preps[0] || { json: {} }).json) || {};
const sd = worker.structured_data || {};
const text = String(worker.output_text || '').replace(/^#{1,6}\s+/gm, '').replace(/\*\*/g, '').replace(/\*/g, '').trim();
if (sd.speak === false || sd.speak === 'false' || !text) {
  return [];
}
const body = text.length > 4000 ? text.slice(0, 3990) + '\u2026' : text;
const ctx = prep.context_data || {};
if (String(ctx.channel || '') === 'telegram') {
  return [{ json: { channel: 'telegram', chat_id: ctx.chat_id, text: body } }];
}
return [{
  json: {
    channel: 'whatsapp',
    text: body,
    to: ctx.group_id,
    phoneNumberId: ctx.phone_number_id
  }
}];
